  idle: { unbooked: IDLE_UNBOOKED, booked: IDLE_BOOKED },
  flushing: { unbooked: FLUSHING_UNBOOKED, booked: FLUSHING_BOOKED },
  disposing: { unbooked: DISPOSING_UNBOOKED, booked: DISPOSING_BOOKED },
} as const;

